    margin-top: 0;
}

.preview-light {
    background: #ffffff;
    color: #333;
}

.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #555;
}

.preview-dark .btn-primary {
    background: #90caf9;
    color: #1e1e1e;
}

.preview-system {
    background: #f5f5f5;
    color: #333;
}

.preview-small {
    font-size: 0.8rem;
}

.preview-medium {
    font-size: 1rem;
}

.preview-large {
    font-size: 1.2rem;
}

.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.2;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Utilities */
.loading-text {
